<?php require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/db.php';if(isset($_GET['del'])){$q=$pdo->prepare("DELETE FROM skills WHERE id=?");$q->execute([(int)$_GET['del']]);header('Location: skill.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare("INSERT INTO skills(name,proficiency,level,sort_order) VALUES(?,?,?,?)");$q->execute([trim($_POST['name']),max(0,min(100,(int)$_POST['proficiency'])),trim($_POST['level']), (int)$_POST['sort_order']]);}$skills=$pdo->query("SELECT * FROM skills ORDER BY sort_order,name")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Skills</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="admin-wrap"><a class="text-link" href="dashboard.php">← Dashboard</a><h1>Skills & <em>tools.</em></h1><form class="form-card" method="post"><label>Skill name</label><input name="name" required><label>Proficiency (0–100)</label><input type="number" name="proficiency" min="0" max="100" value="80"><label>Level label (e.g. Advanced)</label><input name="level"><label>Sort order</label><input type="number" name="sort_order" value="1"><button>Add skill</button></form><table class="table"><?php foreach($skills as $s):?><tr><td><?=htmlspecialchars($s['name'])?></td><td><?=$s['proficiency']?>%</td><td><a href="?del=<?=$s['id']?>" onclick="return confirm('Remove skill?')">Delete</a></td></tr><?php endforeach;?></table></div></body></html>